import { NgIf, NgTemplateOutlet } from '@angular/common';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  HostBinding,
  Input,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';

@Component({
  selector: 'q-wizard-step',
  imports: [NgIf, NgTemplateOutlet],
  templateUrl: './wizard-step.component.html',
  styleUrls: ['./wizard-step.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QWizardStepComponent {
  @Input() title = '';
  @Input() wizardName = '';
  @Input() parentStepTitle = '';
  @Input() isScreenSmallDown = false;
  @Input() template: TemplateRef<HTMLElement> | null = null;
  @Input({ transform: booleanAttribute }) showPageTitle = true;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-wizard-step';

  @ViewChild('stepTitleEl', { read: ElementRef }) _titleElement!: ElementRef;

  @HostBinding('class') hostClass = 'q-wizard-step';
}
