import { BreakpointObserver, BreakpointState } from '@angular/cdk/layout';
import { AsyncPipe, NgIf, NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChildren,
  ElementRef,
  EventEmitter,
  HostBinding,
  Input,
  NgZone,
  OnDestroy,
  OnInit,
  Output,
  QueryList,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  inject,
  DOCUMENT,
} from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import { QBannerComponent } from '@questrade/allspark-angular-components/banner';
import { QButtonComponent } from '@questrade/allspark-angular-components/button';
import { QKebabCasePipe } from '@questrade/allspark-angular-components/core/pipes';
import {
  QDestroyService,
  QSharedResizeObserverService,
} from '@questrade/allspark-angular-components/core/services';
import { isPresent } from '@questrade/allspark-angular-components/core/utils';
import {
  QStepperActiveIndex,
  QStepperComponent,
} from '@questrade/allspark-angular-components/stepper';
import { BehaviorSubject, Observable, debounceTime, delay, of, skip, take, takeUntil } from 'rxjs';

import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { QWizardBeforeStepChangeEvent } from './wizard-step/types/wizard-before-step-change-event.type';
import { QWizardStepChangeEvent } from './wizard-step/types/wizard-step-change-event.interface';
import { QWizardStepCompleteEvent } from './wizard-step/types/wizard-step-complete-event.interface';
import { QWizardStep } from './wizard-step/types/wizard-step.interface';
import { QWizardStepComponent } from './wizard-step/wizard-step.component';
import { QWizardService } from './wizard.service';

@Component({
  selector: 'q-wizard',
  templateUrl: './wizard.component.html',
  styleUrls: ['./wizard.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [
    TranslocoModule,
    NgIf,
    NgTemplateOutlet,
    AsyncPipe,
    QKebabCasePipe,
    QWizardStepComponent,
    QButtonComponent,
    QStepperComponent,
  ],
  providers: [MISSING_KEY_HANDLER, ALLSPARK_SCOPE, QWizardService, QDestroyService],
})
export class QWizardComponent implements OnInit, AfterViewInit, OnDestroy {
  @Output() readonly stepChanged = new EventEmitter<QWizardStepChangeEvent>();
  @Output() readonly stepCompleted = new EventEmitter<QWizardStepCompleteEvent>();
  @Output() readonly primaryButtonClicked = new EventEmitter<Event>();
  @Output() readonly secondaryButtonClicked = new EventEmitter<Event>();

  @Input() wizardName = '';
  @Input() customStepFooterTemplate: TemplateRef<HTMLElement> | null = null;
  @Input() beforeActiveStepChangeJob: QWizardBeforeStepChangeEvent | null = null;
  @Input() beforeBackStepJob!: Observable<boolean>;
  @Input() beforeNextStepJob!: Observable<boolean>;
  @Input() primaryButtonTranslationKey = 'allspark.wizard.next';
  @Input() secondaryButtonTranslationKey = 'allspark.wizard.back';
  @Input({ transform: booleanAttribute }) showDefaultStepFooter = true;
  @Input({ transform: booleanAttribute }) disablePrimaryButton = false;
  @Input({ transform: booleanAttribute }) disableSecondaryButton = false;
  @Input({ transform: booleanAttribute }) hidePrimaryButton = false;
  @Input({ transform: booleanAttribute }) hideSecondaryButton = false;
  @Input({ transform: booleanAttribute }) stepperShowProgressOnActive = false;
  @Input({ transform: booleanAttribute }) stepperShowProgressOnCompleted = false;
  @Input({ transform: booleanAttribute }) showPageTitle = true;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-wizard';

  @Input() get steps(): QWizardStep[] {
    return this._steps;
  }
  set steps(value: QWizardStep[]) {
    this._steps = value;
    this.wizardService.updateSteps(value);
  }

  @Input() get activeStepId(): string {
    return this._activeStepId;
  }
  set activeStepId(id: string) {
    this._activeStepId = id;

    const updateActiveStep =
      id && id !== this.wizardService.activeStep?.id && this.wizardService.steps?.length;

    if (updateActiveStep) {
      this.wizardService.updateActiveStepById(id);
    }
  }

  @ViewChild(QStepperComponent) _stepper!: QStepperComponent;
  @ViewChild('wizardStepEl') _wizardStep!: QWizardStepComponent;
  @ContentChildren(QBannerComponent, { read: ElementRef }) _banners!: QueryList<ElementRef>;

  _isScreenSmallDown = false;
  _stepContainerHeight = '100%';

  readonly wizardService = inject(QWizardService);

  private _activeStepId = '';
  private _steps: QWizardStep[] = [];
  private readonly _breakpointObserver = inject(BreakpointObserver);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _ngZone = inject(NgZone);
  private readonly _document = inject(DOCUMENT);
  private readonly _sharedResizeObserverService = inject(QSharedResizeObserverService);

  private _isBackLoading$ = new BehaviorSubject<boolean>(false);
  isBackLoading$ = this._isBackLoading$.asObservable();
  private _isNextLoading$ = new BehaviorSubject<boolean>(false);
  isNextLoading$ = this._isNextLoading$.asObservable();

  ngOnInit(): void {
    this._setBreakpointObserver();

    this.wizardService.steps$.pipe(skip(1), takeUntil(this._destroy$)).subscribe(() => {
      if (this._activeStepId) {
        this.wizardService.updateActiveStepById(this.activeStepId);
      }
    });

    this.wizardService.activeStep$
      .pipe(skip(1), takeUntil(this._destroy$))
      .subscribe(() => this._emitStepChange());

    this.wizardService.completedStep$
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => this._emitStepCompleted());
  }

  ngAfterViewInit(): void {
    this._stepper?.stepActivatedByKeyboard
      .pipe(takeUntil(this._destroy$), delay(150))
      .subscribe(() => {
        this._wizardStep?._titleElement?.nativeElement?.focus();
      });

    this._banners.changes.pipe(takeUntil(this._destroy$)).subscribe(() => {
      this._calcStepContainerHeigh();
    });

    this._sharedResizeObserverService
      .observe(this._document.body)
      ?.pipe(takeUntil(this._destroy$), debounceTime(150))
      .subscribe(() => {
        this._ngZone.run(() => {
          this._calcStepContainerHeigh();
        });
      });
  }

  ngOnDestroy(): void {
    this.wizardService.reset();
  }

  _isSecondaryButtonHidden(): boolean {
    let firstStep = this.wizardService.steps?.[0];

    if (firstStep?.subSteps?.length) {
      firstStep = firstStep.subSteps[0];
    }

    return this.wizardService.activeStep?.id === firstStep?.id;
  }

  _onPrimaryButtonClicked(): void {
    this._isNextLoading$.next(true);
    (this.beforeNextStepJob || of(true)).pipe(take(1)).subscribe({
      next: (success: boolean) => {
        if (success) {
          this._beforeNextStepJobSuccess();
        } else {
          this._beforeNextStepJobFail();
        }
      },
      error: () => this._beforeNextStepJobFail(),
      complete: () => this._isNextLoading$.next(false),
    });

    this.primaryButtonClicked.emit();
  }

  _onSecondaryButtonClicked(): void {
    this._isBackLoading$.next(true);
    (this.beforeBackStepJob || of(true)).pipe(take(1)).subscribe({
      next: (success: boolean) => {
        if (success) {
          this._beforeBackStepJobSuccess();
        } else {
          this._beforeBackStepJobFail();
        }
      },
      error: () => this._beforeBackStepJobFail(),
      complete: () => this._isBackLoading$.next(false),
    });

    this.secondaryButtonClicked.emit();
  }

  _onStepperActiveIndexChange(indexes: QStepperActiveIndex): void {
    const { stepIndex, subStepIndex } = indexes;
    const steps = this.wizardService.steps;

    if (!steps?.length) return;

    const stepIdToActivate = !isPresent(subStepIndex)
      ? steps[stepIndex].id
      : steps[stepIndex]?.subSteps?.[subStepIndex].id;

    if (!stepIdToActivate) return;

    this.wizardService.updateActiveStepById(stepIdToActivate);
  }

  _onBeforeActiveStepChange = (
    fromIndex: QStepperActiveIndex,
    toIndex: QStepperActiveIndex,
  ): Observable<boolean> => {
    if (this.beforeActiveStepChangeJob) {
      const fromWizardStep = this.wizardService.getWizardStepByStepperIndex(fromIndex);
      const toWizardStep = this.wizardService.getWizardStepByStepperIndex(toIndex);

      if (fromWizardStep && toWizardStep) {
        return this.beforeActiveStepChangeJob(fromWizardStep, toWizardStep);
      }

      // if fromWizardStep and toWizardStep are not found, block the navigation as fallback
      return of(false);
    }

    return of(true);
  };

  private _setBreakpointObserver(): void {
    this._breakpointObserver
      .observe(['(max-width: 1019px)'])
      .pipe(takeUntil(this._destroy$))
      .subscribe((result: BreakpointState) => {
        this._isScreenSmallDown = result.matches;
        this._cdr.markForCheck();
      });
  }

  private _beforeBackStepJobFail(): void {
    this._isBackLoading$.next(false);
  }

  private _beforeNextStepJobFail(): void {
    this._isNextLoading$.next(false);
  }

  private _beforeNextStepJobSuccess(): void {
    this._isNextLoading$.next(false);
    this.wizardService.goNext();
  }

  private _beforeBackStepJobSuccess(): void {
    this._isBackLoading$.next(false);
    this.wizardService.goBack();
  }

  private _emitStepChange(): void {
    this.stepChanged.emit({
      ...(this.wizardService.activeStep && { activeStep: this.wizardService.activeStep }),
      ...(this.wizardService.parentStep && { parentStep: this.wizardService.parentStep }),
      steps: this.wizardService.steps,
    });
  }

  private _emitStepCompleted(): void {
    this.stepCompleted.emit({
      ...(this.wizardService.activeStep && { completedStep: this.wizardService.activeStep }),
      ...(this.wizardService.parentStep && { parentStep: this.wizardService.parentStep }),
      steps: this.wizardService.steps,
    });
  }

  private _calcStepContainerHeigh(): void {
    let calculatedHeight = '100%';

    if (this._banners.length > 0) {
      const totalHeight = this._banners
        .map((bannerEl) => bannerEl.nativeElement?.offsetHeight)
        .reduce((prevHeight: number, currHeight: number) => prevHeight + currHeight, 0);
      calculatedHeight = `calc(100% - ${totalHeight}px)`;
    }

    if (this._stepContainerHeight !== calculatedHeight) {
      this._stepContainerHeight = calculatedHeight;
      this._cdr.markForCheck();
    }
  }
}
